begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
-- Entire fixture (including accounts and media) rolls back. Never targets cloud.
truncate page_revision_blocks,promotion_revision_media,cms_promotion_identity,media_audit_events,revision_media_refs,media_versions,media_assets,content_publication_events,content_publication_state,content_revisions,content_documents;
create temporary table fixture(payload jsonb,baseline uuid,draft uuid,restored uuid,asset uuid,projection jsonb);
grant select,update on fixture to authenticated,anon,service_role;
insert into fixture(payload) values ('{"schemaVersion":1,"publicTitle":"Baseline","h1":"Baseline h1","eyebrow":"Eyebrow","intro":"Intro","imageAlt":"Alt","signsTitle":"Signs","signsDescription":"Signs intro","processTitle":"Process","processDescription":"Process intro","benefitsDescription":"Benefits intro","resultDescription":"Result","seoTitle":"Baseline SEO","seoDescription":"Baseline description","images":["/images/services/delicate-upholstery-cleaning.jpeg"],"signs":["Sign"],"process":["Step"],"benefits":["Benefit"],"faqs":[{"question":"Question","answer":"Answer"}],"relatedLinks":[{"label":"Mattress","href":"/mattress-cleaning"}]}');
select is(cms_import_static_pilot_media(),'d0000000-0000-4000-8000-000000000001'::uuid,'stable static identity');
update fixture set baseline=cms_import_service_baseline(payload);
select is(cms_import_static_pilot_media(),'d0000000-0000-4000-8000-000000000001'::uuid,'bootstrap idempotent');
select is((select count(*)::int from media_assets),1,'one static asset');
select is((select count(*)::int from media_versions),1,'one static version');
select is((select count(*)::int from media_audit_events),1,'one bootstrap event');
select ok((select actor_id is null and kind='bootstrap' from media_audit_events),'bootstrap is operator, not invented admin');
select is((select count(*)::int from revision_media_refs),3,'baseline has three explicit roles');
select is((select storage_path from media_versions),'/images/services/delicate-upholstery-cleaning.jpeg','legacy path preserved');
select is((select alt_text from revision_media_refs where usage_role='hero'),'Alt','original hero alt preserved');
select ok(relrowsecurity and relforcerowsecurity,relname||' forced RLS') from pg_class where oid in ('media_assets'::regclass,'media_versions'::regclass,'revision_media_refs'::regclass,'media_audit_events'::regclass);
insert into auth.users(id,invited_at) values
 ('40000000-0000-4000-8000-000000000001',null),
 ('40000000-0000-4000-8000-000000000002',null),
 ('40000000-0000-4000-8000-000000000003',null),
 ('40000000-0000-4000-8000-000000000004',now());
insert into cms_admin_members(user_id,is_active) values
 ('40000000-0000-4000-8000-000000000001',true),
 ('40000000-0000-4000-8000-000000000003',false),
 ('40000000-0000-4000-8000-000000000004',true);
set local role anon;
select throws_ok($$select * from media_assets$$,'42501',null,'anonymous cannot enumerate media_assets');
select throws_ok($$select * from media_versions$$,'42501',null,'anonymous cannot enumerate media_versions');
select throws_ok($$select * from revision_media_refs$$,'42501',null,'anonymous cannot enumerate revision_media_refs');
select throws_ok($$select * from media_audit_events$$,'42501',null,'anonymous cannot enumerate media_audit_events');
select throws_ok($$select cms_media_library()$$,'42501',null,'anonymous cannot inspect library');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000002","aal":"aal2","role":"authenticated"}',true);
select is((select count(*)::int from media_assets),0,'nonmember cannot read media_assets');
select is((select count(*)::int from media_versions),0,'nonmember cannot read media_versions');
select is((select count(*)::int from revision_media_refs),0,'nonmember cannot read revision_media_refs');
select is((select count(*)::int from media_audit_events),0,'nonmember cannot read media_audit_events');
select throws_ok($$select cms_media_library()$$,'42501',null,'nonmember denied library');
select throws_ok($$select cms_media_detail('d0000000-0000-4000-8000-000000000001')$$,'42501',null,'nonmember denied detail');
select throws_ok($$select cms_read_revision_media((select baseline from fixture))$$,'42501',null,'nonmember denied private references');
select throws_ok($$select cms_update_media_asset('d0000000-0000-4000-8000-000000000001',1,'archive')$$,'42501',null,'nonmember denied archive');
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000001","aal":"aal1","role":"authenticated"}',true);
select is((select count(*)::int from media_assets),0,'AAL1 cannot read media_assets');
select is((select count(*)::int from media_versions),0,'AAL1 cannot read media_versions');
select is((select count(*)::int from revision_media_refs),0,'AAL1 cannot read revision_media_refs');
select is((select count(*)::int from media_audit_events),0,'AAL1 cannot read media_audit_events');
select throws_ok($$select cms_media_library()$$,'42501',null,'AAL1 denied library');
select throws_ok($$select cms_media_detail('d0000000-0000-4000-8000-000000000001')$$,'42501',null,'AAL1 denied detail');
select throws_ok($$select cms_read_revision_media((select baseline from fixture))$$,'42501',null,'AAL1 denied private references');
select throws_ok($$select cms_update_media_asset('d0000000-0000-4000-8000-000000000001',1,'archive')$$,'42501',null,'AAL1 denied archive');
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000003","aal":"aal2","role":"authenticated"}',true);
select is((select count(*)::int from media_assets),0,'inactive cannot read media_assets');
select is((select count(*)::int from media_versions),0,'inactive cannot read media_versions');
select is((select count(*)::int from revision_media_refs),0,'inactive cannot read revision_media_refs');
select is((select count(*)::int from media_audit_events),0,'inactive cannot read media_audit_events');
select throws_ok($$select cms_media_library()$$,'42501',null,'inactive denied library');
select throws_ok($$select cms_media_detail('d0000000-0000-4000-8000-000000000001')$$,'42501',null,'inactive denied detail');
select throws_ok($$select cms_read_revision_media((select baseline from fixture))$$,'42501',null,'inactive denied private references');
select throws_ok($$select cms_update_media_asset('d0000000-0000-4000-8000-000000000001',1,'archive')$$,'42501',null,'inactive denied archive');
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000004","aal":"aal2","role":"authenticated"}',true);
select is((select count(*)::int from media_assets),0,'pending cannot read media_assets');
select is((select count(*)::int from media_versions),0,'pending cannot read media_versions');
select is((select count(*)::int from revision_media_refs),0,'pending cannot read revision_media_refs');
select is((select count(*)::int from media_audit_events),0,'pending cannot read media_audit_events');
select throws_ok($$select cms_media_library()$$,'42501',null,'pending denied library');
select throws_ok($$select cms_media_detail('d0000000-0000-4000-8000-000000000001')$$,'42501',null,'pending denied detail');
select throws_ok($$select cms_read_revision_media((select baseline from fixture))$$,'42501',null,'pending denied private references');
select throws_ok($$select cms_update_media_asset('d0000000-0000-4000-8000-000000000001',1,'archive')$$,'42501',null,'pending denied archive');
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000001","aal":"aal2","role":"authenticated"}',true);
select is(jsonb_array_length(cms_media_library()),1,'active completed AAL2 library');
select is(jsonb_array_length(cms_read_revision_media((select baseline from fixture))),3,'AAL2 reads private references');
select throws_ok($$select cms_register_media_version(null,null,null,null,null,'40000000-0000-4000-8000-000000000001')$$,'42501',null,'browser cannot forge validated upload');
select throws_ok($$select cms_import_static_pilot_media()$$,'42501',null,'browser cannot bootstrap');
select throws_ok($$select cms_revision_media_projection((select baseline from fixture))$$,'42501',null,'internal projection not exposed');
select throws_ok($$delete from media_assets$$,'42501',null,'AAL2 cannot directly delete media_assets');
select throws_ok($$delete from media_versions$$,'42501',null,'AAL2 cannot directly delete media_versions');
select throws_ok($$delete from revision_media_refs$$,'42501',null,'AAL2 cannot directly delete revision_media_refs');
select throws_ok($$delete from media_audit_events$$,'42501',null,'AAL2 cannot directly delete media_audit_events');
select throws_ok($$update media_assets set alt_text='bypass'$$,'42501',null,'AAL2 cannot bypass metadata concurrency');
select throws_ok($$insert into media_assets(alt_text) values('forged')$$,'42501',null,'AAL2 cannot directly create assets');
select throws_ok($$update media_versions set content_hash=repeat('a',64)$$,'42501',null,'AAL2 cannot overwrite physical metadata');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select cms_register_media_version(null,null,'d2000000-0000-4000-8000-000000000001','{}','{"altText":"Alt","caption":"","folder":""}','40000000-0000-4000-8000-000000000003')$$,'42501',null,'server attestation independently rejects inactive actor');
update fixture set asset=cms_register_media_version(null,null,'d2000000-0000-4000-8000-000000000001','{"byteSize":200,"width":12,"height":8,"contentHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","originalFilename":"first.png"}','{"altText":"Library alt","caption":"Original caption","folder":"Pilot"}','40000000-0000-4000-8000-000000000001');
reset role;
select is((select count(*)::int from media_versions),2,'validated upload adds immutable version');
select is((select storage_path from media_versions where id='d2000000-0000-4000-8000-000000000001'),'d2000000-0000-4000-8000-000000000001.webp','server UUID path, never original filename');
select is((select created_by from media_versions where id='d2000000-0000-4000-8000-000000000001'),'40000000-0000-4000-8000-000000000001'::uuid,'human upload actor recorded');
select ok(cms_read_public_media_version('d2000000-0000-4000-8000-000000000001') is null,'unreferenced upload remains private');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000001","aal":"aal2","role":"authenticated"}',true);
update fixture set draft=cms_save_service_draft(1,baseline,payload||'{"schemaVersion":2,"images":["d2000000-0000-4000-8000-000000000001"]}');
select is((select count(*)::int from revision_media_refs where revision_id=(select draft from fixture)),3,'v2 creates relational references');
select is((select published_revision_id from content_publication_state),(select baseline from fixture),'image selection only saves draft');
select ok(cms_read_public_media_version('d2000000-0000-4000-8000-000000000001') is null,'draft image not exposed by public RPC');
select is(cms_publish_service_revision(2,(select draft from fixture)),(select draft from fixture),'explicit publish media revision');
update fixture set projection=cms_read_published_pilot();
select is(cms_read_public_media_version('d2000000-0000-4000-8000-000000000001')->>'id','d2000000-0000-4000-8000-000000000001','published bytes can be served');
select is(cms_update_media_asset((select asset from fixture),1,'metadata','{"altText":"Changed default","caption":"Changed caption","folder":"Next"}'),(select asset from fixture),'edit metadata');
select is(cms_read_published_pilot(),(select projection from fixture),'metadata edit cannot change published alt/caption');
select throws_ok($$select cms_update_media_asset((select asset from fixture),1,'metadata','{"altText":"Stale","caption":"","folder":""}')$$,'PT409',null,'stale metadata denied');
select throws_ok($$select cms_update_media_asset((select asset from fixture),1,'archive')$$,'PT409',null,'stale archive denied');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(cms_register_media_version((select asset from fixture),2,'d2000000-0000-4000-8000-000000000002','{"byteSize":201,"width":12,"height":8,"contentHash":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","originalFilename":"second.png"}','{"altText":"Replacement default","caption":"","folder":""}','40000000-0000-4000-8000-000000000001'),(select asset from fixture),'replacement creates new physical version');
select throws_ok($$select cms_register_media_version((select asset from fixture),2,'d2000000-0000-4000-8000-000000000003','{}','{"altText":"Alt","caption":"","folder":""}','40000000-0000-4000-8000-000000000001')$$,'PT409',null,'stale replacement rejected before insert');
reset role;
select is((select count(*)::int from media_versions),3,'stale replacement left no version');
select is((select alt_text from media_assets where id=(select asset from fixture)),'Replacement default','replacement metadata updates atomically without changing reference snapshots');
select is(cms_read_published_pilot(),(select projection from fixture),'replacement leaves published output exact');
select is((select version_number from media_versions where id='d2000000-0000-4000-8000-000000000002'),2,'monotonic media version number');
select is((select count(*)::int from revision_media_refs where media_version_id='d2000000-0000-4000-8000-000000000001'),3,'old version references preserved');
select ok(cms_read_public_media_version('d2000000-0000-4000-8000-000000000002') is null,'new replacement stays private until explicitly published');
select throws_ok($$delete from media_versions$$,'55000',null,'operator cannot delete retained media_versions');
select throws_ok($$delete from revision_media_refs$$,'55000',null,'operator cannot delete retained revision_media_refs');
select throws_ok($$delete from media_audit_events$$,'55000',null,'operator cannot delete retained media_audit_events');
select throws_ok($$delete from media_assets$$,'55000',null,'operator cannot delete retained media_assets');
select throws_ok($$update media_versions set byte_size=1$$,'55000',null,'operator cannot mutate historical media');
select throws_ok($$update revision_media_refs set alt_text='changed'$$,'55000',null,'reference alt immutable');
select throws_ok($$update media_audit_events set kind='archive'$$,'55000',null,'audit immutable');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000001","aal":"aal2","role":"authenticated"}',true);
update fixture set restored=cms_save_service_draft(3,draft,payload||'{"schemaVersion":2,"images":["d2000000-0000-4000-8000-000000000002"]}');
select is((select media_version_id from revision_media_refs where revision_id=(select restored from fixture) and usage_role='hero'),'d2000000-0000-4000-8000-000000000002'::uuid,'new draft explicitly selects new version');
select is(cms_read_published_pilot(),(select projection from fixture),'new selection leaves published projection unchanged');
select is(cms_update_media_asset((select asset from fixture),3,'archive'),(select asset from fixture),'archive retains referenced asset');
select is(cms_read_published_pilot(),(select projection from fixture),'archive cannot change published output');
select is((cms_media_detail((select asset from fixture))->'asset'->>'status'),'archived','archive state visible in detail');
-- A draft keeping an already selected archived version is allowed; new selection is not.
select throws_ok($$select cms_save_service_draft(4,(select restored from fixture),(select payload||'{"schemaVersion":2,"images":["d2000000-0000-4000-8000-000000000001"]}' from fixture))$$,'55000',null,'cannot newly select archived version');
update fixture set restored=cms_save_service_draft(4,restored,null,draft);
select isnt((select restored from fixture),(select draft from fixture),'rollback creates new content identity');
select is((select jsonb_agg(to_jsonb(r)-'revision_id' order by usage_role,position) from revision_media_refs r where revision_id=(select restored from fixture)),(select jsonb_agg(to_jsonb(r)-'revision_id' order by usage_role,position) from revision_media_refs r where revision_id=(select draft from fixture)),'rollback copies exact historical versions, alt and caption even archived');
select is(cms_publish_service_revision(5,(select restored from fixture)),(select restored from fixture),'archived historical media can be republished by rollback');
select is(cms_read_published_pilot()->'payload',(select projection->'payload' from fixture),'rollback published body unchanged');
select is(cms_update_media_asset((select asset from fixture),4,'restore'),(select asset from fixture),'restore asset for new selection');
select is((cms_media_detail((select asset from fixture))->'asset'->>'status'),'available','restored available');
select is((select count(*)::int from media_audit_events where actor_id='40000000-0000-4000-8000-000000000001'),5,'upload replace metadata archive restore each audited');
reset role;
select throws_ok($$insert into revision_media_refs values((select baseline from fixture),'d9000000-0000-4000-8000-000000000001','hero',1,'Alt','')$$,'23503',null,'reference integrity rejects nonexistent version');
update cms_admin_members set is_active=false where user_id='40000000-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(*)::int from media_assets),0,'membership revocation takes effect immediately');
select throws_ok($$select cms_update_media_asset((select asset from fixture),5,'archive')$$,'42501',null,'stale AAL2 claims cannot archive after revocation');
reset role;
select * from finish();
rollback;
